<template>
  <section class="effect-picker" aria-label="特效选择">
    <header><div><strong>特效选择</strong><small>{{ activeKind==='text'?'文本特效使用示例气泡预览':activeKind==='interaction'?'双方头像会在独立动画层中互动，不推动消息布局':'屏幕特效在下方示例画布内预览' }}</small></div></header>
    <nav v-if="kindCount>1" class="effect-kind-tabs" :style="{'--kind-count':kindCount}"><button v-if="showText" type="button" :class="{active:activeKind==='text'}" @click="activeKind='text'">文本特效</button><button v-if="showScreen" type="button" :class="{active:activeKind==='screen'}" @click="activeKind='screen'">屏幕特效</button><button v-if="showInteraction" type="button" :class="{active:activeKind==='interaction'}" @click="chooseInteractionKind">互动特效</button></nav>
	    <div v-if="showText||showScreen||showPersistent" :key="previewKey" class="effect-preview" :class="previewClass" :style="previewStyle">
	      <i class="effect-preview__screen"></i>
	      <span v-if="persistentEffect==='storm'||persistentEffect==='snowfall'" class="preview-weather" :class="`preview-weather--${persistentEffect}`"><i v-for="particle in weatherParticles" :key="particle" :style="weatherParticleStyle(particle,persistentEffect)"></i></span>
      <div class="effect-preview__message"><span class="effect-preview__avatar">洛</span><div><small>示例角色</small><p><span v-for="(token,index) in previewTokens" :key="index" :class="`preview-token preview-token--${normalizedTextEffect}`">{{ token }}</span></p></div></div>
      <button class="effect-preview-replay" type="button" aria-label="重播特效" @click="requestPreview"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z" /></svg><span>预览</span></button>
    </div>
    <div v-if="showInteraction&&activeKind==='interaction'" :key="`interaction-${previewKey}`" class="interaction-preview" :class="[`interaction-preview--${interactionEffect}`,`interaction-preview--reaction-${interactionReaction}`,{'interaction-preview--reverse':sourcePosition==='right','interaction-preview--source-only':!targetName}]" :style="interactionPreviewStyle">
      <button class="effect-preview-replay" type="button" aria-label="重播互动特效" @click="requestPreview"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z" /></svg><span>预览</span></button>
      <span class="interaction-preview__actor interaction-preview__actor--source"><img v-if="sourceAvatar" :src="sourceAvatar" alt="发起角色头像" /><i v-else>{{ sourceName.slice(0,1) }}</i><small>{{ sourceName }}</small></span>
      <span v-if="!interactionEmoji&&(interactionEffect==='magic'||interactionEffect==='magic-circle')" class="magic-array"><i></i><i></i><i></i></span>
      <span v-if="interactionEffect!=='magic-circle'" class="interaction-preview__projectile" :class="{'interaction-preview__projectile--custom':interactionEmoji}" :style="interactionPreviewStyle"><template v-if="interactionEmoji">{{ interactionEmoji }}</template><template v-else-if="interactionEffect==='throw'">🪨</template><span v-else-if="interactionEffect==='heart'" class="interaction-heart-particles">♥</span><span v-else-if="interactionEffect==='surprise'" class="interaction-surprise-mark">!</span><span v-else-if="interactionEffect==='impact'" class="interaction-impact-burst"></span><span v-else-if="interactionEffect==='bullet'" class="interaction-bullet-core"></span><span v-else-if="interactionEffect==='magic'" class="interaction-magic-orb"></span><span v-else class="interaction-preview__sprite"></span></span>
      <span v-if="targetName" class="interaction-preview__actor interaction-preview__actor--target"><img v-if="targetAvatar" :src="targetAvatar" alt="目标角色头像" /><i v-else>{{ targetName.slice(0,1) }}</i><small>{{ targetName }}</small></span>
    </div>

    <div v-if="showText&&activeKind==='text'" class="effect-picker__section"><h4>文字出现动画 <small>采用经过调校的预制节奏</small></h4><div class="effect-card-grid"><button v-for="option in textOptions" :key="option.value" type="button" :class="{active:textEffect===option.value}" @click="chooseText(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="showScreen&&activeKind==='screen'" class="effect-picker__section"><h4>屏幕动画底子 <small>选择运动与画面形态</small></h4><div class="effect-card-grid effect-card-grid--screen"><button v-for="option in screenOptions" :key="option.value" type="button" :class="{active:screenEffect===option.value}" @click="chooseScreen(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
	<div v-if="showScreen&&activeKind==='screen'" class="effect-picker__section custom-presets"><h4>我的屏幕特效预设 <small>预设的创建、分享码导入和分类请在登录后的个人中心完成</small></h4><section v-for="group in presetGroups" :key="group.id" class="preset-folder"><strong>{{ group.name }}</strong><div class="effect-card-grid"><button v-for="preset in group.items" :key="preset.id" type="button" @click="applyPreset(preset)"><b>★</b><span>{{ preset.name }}</span></button></div></section><p v-if="!presetGroups.length" class="preset-empty">登录后可在个人中心创建自己的屏幕特效预设。</p></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section"><slot name="interaction-target" /><h4>一、互动方式 <small>选择双方头像的运动和投射物轨迹</small></h4><div class="effect-card-grid"><button v-for="option in interactionOptions" :key="option.value" type="button" :class="{active:interactionEffect===option.value}" @click="chooseInteraction(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section"><h4>二、目标反应 <small>可以回应、倒下、碎裂、灰化或完全不回应</small></h4><div class="effect-card-grid"><button v-for="option in reactionOptions" :key="option.value" type="button" :class="{active:interactionReaction===option.value}" @click="chooseReaction(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section interaction-resource"><h4>三、互动资源与速度 <small>{{ interactionEffect==='throw'?'投掷 Emoji 会直接使用输入内容':'留空使用内置动画资源，填写后改用自定义符号' }}</small></h4><div class="picker-palette"><button v-for="option in colorOptions" :key="option.value" type="button" :class="{active:interactionColor===option.value}" :aria-label="option.label" @click="chooseInteractionColor(option.value)"><i :style="{background:option.swatch||option.hex}"></i><span>{{ option.label }}</span><b v-if="interactionColor===option.value">✓</b></button></div><div class="interaction-resource__controls"><label class="interaction-emoji"><span>{{ interactionEffect==='throw'?'投掷内容':'自定义符号' }}</span><n-input :value="interactionEmoji" maxlength="8" :placeholder="interactionEffect==='throw'?'默认 🪨':'留空使用内置动画'" @update:value="chooseEmoji" /></label><label class="interaction-speed"><span>互动速度</span><n-input-number :value="interactionSpeedPercent" :min="25" :max="400" :step="5" :show-button="false" @update:value="chooseInteractionSpeed($event ?? 100)" /><small>%</small></label></div></div>
    <div v-if="showInteraction&&activeKind==='interaction'" class="effect-picker__section custom-presets"><h4>我的互动特效预设 <small>预设的创建、分享码导入和分类请在登录后的个人中心完成</small></h4><section v-for="group in interactionPresetGroups" :key="group.id" class="preset-folder"><strong>{{ group.name }}</strong><div class="effect-card-grid"><button v-for="preset in group.items" :key="preset.id" type="button" @click="applyPreset(preset)"><b>★</b><span>{{ preset.name }}</span></button></div></section><p v-if="!interactionPresetGroups.length" class="preset-empty">登录后可在个人中心创建自己的互动特效预设。</p></div>
    <div v-if="showPersistent" class="effect-picker__section"><h4>持续特效形态</h4><div class="effect-card-grid"><button v-for="option in persistentOptions" :key="option.value" type="button" :class="{active:persistentEffect===option.value}" @click="choosePersistent(option.value)"><b>{{ option.glyph }}</b><span>{{ option.label }}</span></button></div></div>
    <div v-if="(showScreen&&activeKind==='screen')||showPersistent" class="effect-picker__section" :class="{'effect-picker__section--locked':materialColorLocked}"><h4>二、预制颜色 <small>{{ materialColorLocked?'该特效使用素材原色，不可调色':'只改变颜色，不改变动画' }}</small></h4><div class="picker-palette"><button v-for="option in colorOptions" :key="option.value" type="button" :disabled="materialColorLocked" :class="{active:!materialColorLocked&&color===option.value}" :aria-label="materialColorLocked?`${option.label}（素材特效不可调色）`:option.label" @click="chooseColor(option.value)"><i :style="{background:option.swatch||option.hex}"></i><span>{{ option.label }}</span><b v-if="!materialColorLocked&&color===option.value">✓</b></button></div></div>
    <div v-if="showParameters&&activeKind==='screen'" class="effect-picker__section effect-parameters">
      <h4>三、播放参数 <small>控制屏幕动画节奏，不改变消息停留时间</small></h4>
      <div>
        <label><span>持续时间</span><n-input-number :value="durationMs" :min="120" :max="10000" :step="50" :show-button="false" @update:value="chooseDuration($event ?? 1200)" /><small>ms</small></label>
        <label><span>播放速度</span><n-input-number :value="speedPercent" :min="25" :max="400" :step="5" :show-button="false" @update:value="chooseSpeed($event ?? 100)" /><small>%</small></label>
        <label><span>重复次数</span><n-input-number :value="repeat" :min="1" :max="12" :step="1" :show-button="false" @update:value="chooseRepeat($event ?? 1)" /><small>次</small></label>
      </div>
    </div>
    <div v-if="showPersistent" class="effect-picker__section effect-parameters effect-parameters--persistent">
      <h4>三、区间参数 <small>分别控制强度、覆盖透明度和运动速度</small></h4>
      <div>
        <label><span>效果强度</span><n-input-number :value="persistentIntensity" :min="10" :max="200" :step="5" :show-button="false" @update:value="choosePersistentIntensity($event ?? 100)" /><small>%</small></label>
        <label><span>覆盖透明度</span><n-input-number :value="persistentOpacity" :min="5" :max="100" :step="5" :show-button="false" @update:value="choosePersistentOpacity($event ?? 100)" /><small>%</small></label>
        <label><span>运动速度</span><n-input-number :value="persistentSpeed" :min="10" :max="400" :step="5" :show-button="false" @update:value="choosePersistentSpeed($event ?? 100)" /><small>%</small></label>
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useEffectPresets, type EffectPreset, type InteractionEffectPresetConfig, type ScreenEffectPresetConfig } from "~/composables/useEffectPresets";
import { INTERACTION_DEFAULT_REACTION } from "~/story/message-effects";
import type { StoryEffectColor, StoryInteractionEffect, StoryInteractionReaction, StoryPersistentEffect, StoryScreenEffect, StoryStreamTokenAnimation } from "~/story/types";
import { vfxAssets } from "~/story/vfx-assets";

const props=withDefaults(defineProps<{showText?:boolean;showScreen?:boolean;showInteraction?:boolean;showPersistent?:boolean;showParameters?:boolean;textEffect?:"inherit"|StoryStreamTokenAnimation;screenEffect?:StoryScreenEffect;persistentEffect?:StoryPersistentEffect|null;color?:StoryEffectColor;durationMs?:number;speedPercent?:number;repeat?:number;persistentIntensity?:number;persistentOpacity?:number;persistentSpeed?:number;interactionEffect?:"none"|StoryInteractionEffect;interactionReaction?:StoryInteractionReaction;interactionEmoji?:string;interactionColor?:StoryEffectColor;interactionSpeedPercent?:number;sourceName?:string;sourceAvatar?:string;sourcePosition?:"left"|"right"|"narrator";targetName?:string;targetAvatar?:string}>(),{showText:false,showScreen:false,showInteraction:false,showPersistent:false,showParameters:false,textEffect:"inherit",screenEffect:"none",persistentEffect:null,color:"auto",durationMs:1200,speedPercent:100,repeat:1,persistentIntensity:100,persistentOpacity:100,persistentSpeed:100,interactionEffect:"none",interactionReaction:"stagger",interactionEmoji:"",interactionColor:"auto",interactionSpeedPercent:100,sourceName:"发送者",sourceAvatar:"",sourcePosition:"left",targetName:"",targetAvatar:""});
const emit=defineEmits<{text:["inherit"|StoryStreamTokenAnimation];screen:[StoryScreenEffect];persistent:[StoryPersistentEffect];color:[StoryEffectColor];duration:[number];speed:[number];repeat:[number];persistentIntensity:[number];persistentOpacity:[number];persistentSpeed:[number];previewScreen:[];interaction:["none"|StoryInteractionEffect];reaction:[StoryInteractionReaction];emoji:[string];interactionColor:[StoryEffectColor];interactionSpeed:[number];previewInteraction:[]}>();
const {presets,folders,loadEffectPresets}=useEffectPresets();onMounted(()=>loadEffectPresets());
function groupPresets(kind:EffectPreset["kind"]){const groups=[{id:"",name:"未分类",items:presets.value.filter(item=>item.kind===kind&&!item.folderId)}];for(const folder of folders.value)groups.push({id:folder.id,name:folder.name,items:presets.value.filter(item=>item.kind===kind&&item.folderId===folder.id)});return groups.filter(group=>group.items.length)}
const presetGroups=computed(()=>groupPresets("screen"));const interactionPresetGroups=computed(()=>groupPresets("interaction"));
const previewKey=ref(0);const replay=()=>{previewKey.value+=1};
const kindCount=computed(()=>Number(props.showText)+Number(props.showScreen)+Number(props.showInteraction));
const activeKind=ref<"text"|"screen"|"interaction">(props.showText?"text":props.showScreen||props.showPersistent?"screen":"interaction");
const previewTokens=["这", "是", "一段", "演出", "预览"];
const weatherParticles=Array.from({length:24},(_,index)=>index);
function weatherParticleStyle(index:number,effect:StoryPersistentEffect|null){const seed=(index*47+13)%101;const base=effect==="storm"?.72+(seed%13)/20:4.2+(seed%27)/10;const duration=base*100/Math.max(10,props.persistentSpeed);return{"--weather-left":`${(index*37+11)%100}%`,"--weather-delay":`${-((index*29)%73)/10}s`,"--weather-particle-duration":`${duration}s`,animationDuration:`${duration}s`,"--weather-size":`${effect==="storm"?14+(seed%24):2+(seed%4)*.7}px`,"--weather-drift":`${((seed%17)-8)*1.3}px`} as Record<string,string>}
const normalizedTextEffect=computed(()=>props.textEffect==="inherit"?"rise":props.textEffect);
const textOptions:Array<{label:string;value:"inherit"|StoryStreamTokenAnimation;glyph:string}>=[{label:"跟随全局",value:"inherit",glyph:"全"},{label:"上浮淡入",value:"rise",glyph:"↑"},{label:"淡入",value:"fade",glyph:"◐"},{label:"模糊聚焦",value:"blur",glyph:"◎"},{label:"重击落字",value:"impact",glyph:"↓"},{label:"急促震颤",value:"shake",glyph:"≈"},{label:"幽灵显现",value:"ghost",glyph:"◌"},{label:"无动画",value:"none",glyph:"—"}];
const screenOptions:Array<{label:string;value:StoryScreenEffect;glyph:string}>=[{label:"无屏幕效果",value:"none",glyph:"—"},{label:"轻微震动",value:"shake-light",glyph:"≈"},{label:"强烈冲击",value:"shake-heavy",glyph:"≋"},{label:"中心绽放",value:"glow",glyph:"✦"},{label:"横向光扫",value:"warm-glow",glyph:"→"},{label:"镜头闪切",value:"cold-flash",glyph:"▰"},{label:"瞬间曝光",value:"flash",glyph:"☀"},{label:"故障闪烁",value:"flicker",glyph:"▥"},{label:"边缘冲击",value:"damage",glyph:"◉"},{label:"双重脉冲",value:"heartbeat",glyph:"♥"},{label:"幕布切黑",value:"blackout",glyph:"■"},{label:"雾化漂移",value:"dream",glyph:"≋"},{label:"聚光收束",value:"vignette",glyph:"◍"},{label:"波纹扩散",value:"ripple",glyph:"◎"},{label:"幕布揭示",value:"curtain",glyph:"▐"},{label:"色散错位",value:"chromatic",glyph:"◒"},{label:"镜头推进",value:"zoom-focus",glyph:"⊙"}];
const interactionOptions:Array<{label:string;value:"none"|StoryInteractionEffect;glyph:string}>=[{label:"无互动",value:"none",glyph:"—"},{label:"投掷 Emoji",value:"throw",glyph:"↗"},{label:"贴近爱心",value:"heart",glyph:"♥"},{label:"施放法术",value:"magic",glyph:"✦"},{label:"展开法阵",value:"magic-circle",glyph:"◎"},{label:"突然惊吓",value:"surprise",glyph:"!"},{label:"近身冲击",value:"impact",glyph:"✹"},{label:"高速子弹",value:"bullet",glyph:"•"},{label:"飞掷刀刃",value:"blade",glyph:"†"}];
const reactionOptions:Array<{label:string;value:StoryInteractionReaction;glyph:string}>=[{label:"不回应",value:"none",glyph:"…"},{label:"跳起来",value:"bounce",glyph:"↑"},{label:"踉跄",value:"stagger",glyph:"≈"},{label:"晕倒",value:"faint",glyph:"↷"},{label:"碎开",value:"shatter",glyph:"◇"},{label:"灰掉",value:"gray",glyph:"◐"},{label:"贴近回应",value:"affection",glyph:"♥"}];
const interactionEmojiDefaults:Record<StoryInteractionEffect,string>={throw:"🪨",heart:"",magic:"","magic-circle":"",surprise:"",impact:"",bullet:"",blade:""};
const defaultInteractionEmoji=computed(()=>props.interactionEffect==="none"?"":interactionEmojiDefaults[props.interactionEffect]);
const persistentOptions:Array<{label:string;value:StoryPersistentEffect;glyph:string}>=[{label:"边缘警戒",value:"low-health",glyph:"▣"},{label:"暗角侵蚀",value:"curse",glyph:"◉"},{label:"流动雾幕",value:"dream-haze",glyph:"≋"},{label:"下雨",value:"storm",glyph:"╲"},{label:"呼吸光环",value:"magic-aura",glyph:"◎"},{label:"镜头雨痕",value:"rain-glass",glyph:"◌"},{label:"镜头血迹",value:"blood-stain",glyph:"●"},{label:"动态飘雪",value:"snowfall",glyph:"❄"}];
const colorOptions:Array<{label:string;value:StoryEffectColor;hex:string;swatch?:string}>=[{label:"自动",value:"auto",hex:"#6bcfc6",swatch:"conic-gradient(#df6070,#d5b34f,#59bf83,#56bec5,#a276d3,#df6070)"},{label:"中性",value:"neutral",hex:"#d9e2df"},{label:"绯红",value:"red",hex:"#df6070"},{label:"橙焰",value:"orange",hex:"#e68a52"},{label:"金辉",value:"gold",hex:"#d5b34f"},{label:"森绿",value:"green",hex:"#59bf83"},{label:"青蓝",value:"cyan",hex:"#56bec5"},{label:"深蓝",value:"blue",hex:"#6595dc"},{label:"幽紫",value:"purple",hex:"#a276d3"},{label:"绯粉",value:"pink",hex:"#d66f9f"}];
const colorHex=computed(()=>colorOptions.find(option=>option.value===props.color)?.hex||colorOptions[0].hex);
const interactionColorHex=computed(()=>colorOptions.find(option=>option.value===props.interactionColor)?.hex||colorOptions[0].hex);
const interactionSprite:Partial<Record<StoryInteractionEffect,string>>={blade:vfxAssets.crescentSlash};
const interactionBaseDuration:Record<StoryInteractionEffect,number>={throw:1900,heart:2200,magic:2600,"magic-circle":2300,surprise:1900,impact:1900,bullet:1750,blade:2100};
const interactionPreviewStyle=computed(()=>({'--interaction-color':interactionColorHex.value,'--interaction-duration':`${Math.round((props.interactionEffect==='none'?1900:interactionBaseDuration[props.interactionEffect])*100/Math.max(25,props.interactionSpeedPercent))}ms`,'--interaction-sprite':`url("${props.interactionEffect==='none'?'':interactionSprite[props.interactionEffect]||''}")`}));
const previewDuration=computed(()=>`${Math.max(80,Math.round((props.showPersistent?900:props.durationMs)*100/Math.max(10,props.showPersistent?props.persistentSpeed:props.speedPercent)))}ms`);
const previewStyle=computed(()=>({'--preview-color':colorHex.value,'--preview-duration':previewDuration.value,'--preview-repeat':String(Math.max(1,props.repeat)),'--persistent-opacity':String(props.persistentOpacity),'--persistent-intensity':String(props.persistentIntensity),'--persistent-speed':String(props.persistentSpeed),'--rain-overlay':`url("${vfxAssets.rainOverlay}")`,'--rain-sheet':`url("${vfxAssets.rainField}")`,'--lens-raindrops':`url("${vfxAssets.lensRaindrops}")`,'--blood-lens-overlay':`url("${vfxAssets.bloodLensOverlay}")`,'--blood-01':`url("${vfxAssets.bloodSplatter01}")`,'--blood-02':`url("${vfxAssets.bloodSplatter02}")`}));
const previewClass=computed(()=>props.showPersistent&&props.persistentEffect?`effect-preview--persistent-${props.persistentEffect}`:props.showScreen?`effect-preview--${props.screenEffect}`:"");
const materialColorLocked=computed(()=>props.showPersistent&&(props.persistentEffect==="rain-glass"||props.persistentEffect==="blood-stain"));
const recommendedRepeat:Partial<Record<StoryScreenEffect,number>>={flicker:3,heartbeat:2};
const recommendedScreenColor:Record<StoryScreenEffect,StoryEffectColor>={none:"auto","shake-light":"neutral","shake-heavy":"orange",glow:"gold","warm-glow":"gold","cold-flash":"cyan",flash:"neutral",flicker:"purple",damage:"red",heartbeat:"pink",blackout:"neutral",dream:"purple",vignette:"blue",ripple:"cyan",curtain:"purple",chromatic:"cyan","zoom-focus":"gold"};
const recommendedPersistentColor:Record<StoryPersistentEffect,StoryEffectColor>={"low-health":"red",curse:"purple","dream-haze":"blue",storm:"cyan","magic-aura":"purple","rain-glass":"cyan","blood-stain":"red",snowfall:"neutral",underwater:"blue","film-grain":"neutral"};
function requestPreview(){if(activeKind.value==='interaction')emit('previewInteraction');else if(activeKind.value==='screen')emit('previewScreen');replay()}function chooseText(value:"inherit"|StoryStreamTokenAnimation){activeKind.value="text";emit("text",value);replay()}function chooseScreen(value:StoryScreenEffect){activeKind.value="screen";emit("screen",value);emit("color",recommendedScreenColor[value]);emit("repeat",recommendedRepeat[value]??1);replay()}function choosePersistent(value:StoryPersistentEffect){emit("persistent",value);emit("color",value==="rain-glass"||value==="blood-stain"?"neutral":recommendedPersistentColor[value]);replay()}function chooseColor(value:StoryEffectColor){if(materialColorLocked.value)return;emit("color",value);replay()}function chooseDuration(value:number){emit("duration",Math.round(value));replay()}function chooseSpeed(value:number){emit("speed",Math.round(value));replay()}function chooseRepeat(value:number){emit("repeat",Math.round(value));replay()}
function chooseInteractionKind(){activeKind.value="interaction";replay()}function chooseInteraction(value:"none"|StoryInteractionEffect){activeKind.value="interaction";emit("interaction",value);if(value!=="none")emit("reaction",INTERACTION_DEFAULT_REACTION[value]);replay()}function chooseReaction(value:StoryInteractionReaction){emit("reaction",value);replay()}function chooseEmoji(value:string){emit("emoji",value);replay()}
function chooseInteractionColor(value:StoryEffectColor){emit("interactionColor",value);replay()}function chooseInteractionSpeed(value:number){emit("interactionSpeed",Math.round(value));replay()}
function choosePersistentIntensity(value:number){emit("persistentIntensity",Math.round(value));replay()}function choosePersistentOpacity(value:number){emit("persistentOpacity",Math.round(value));replay()}function choosePersistentSpeed(value:number){emit("persistentSpeed",Math.round(value));replay()}
function applyPreset(preset:EffectPreset){if(preset.kind==="interaction"){const config=preset.config as InteractionEffectPresetConfig;emit("interaction",config.interactionEffect);emit("reaction",config.reaction);emit("emoji",config.emoji);emit("interactionColor",config.color||"auto");emit("interactionSpeed",config.speedPercent||100);activeKind.value="interaction";replay();return}const config=preset.config as ScreenEffectPresetConfig;emit("screen",config.screenEffect);emit("color",config.color);emit("duration",config.durationMs);emit("speed",config.speedPercent);emit("repeat",config.repeat);replay()}
